package com.cekalix.dao;
import com.cekalix.util.ConexionBD;import java.sql.*;import java.math.*;import java.util.*;
public class CotizacionDAO {
 public int guardar(int cliente,int usuario,int[] ids,int[] cantidades)throws SQLException{if(ids==null||ids.length==0||ids.length!=cantidades.length)throw new SQLException("Agrega productos a la cotización.");try(Connection c=ConexionBD.obtenerConexion()){c.setAutoCommit(false);try{BigDecimal sub=BigDecimal.ZERO;List<BigDecimal> precios=new ArrayList<>();for(int i=0;i<ids.length;i++){if(cantidades[i]<1)throw new SQLException("Cantidad inválida.");try(PreparedStatement p=c.prepareStatement("SELECT precio FROM producto WHERE id_producto=? AND estado=1")){p.setInt(1,ids[i]);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Producto no disponible.");BigDecimal v=r.getBigDecimal(1);precios.add(v);sub=sub.add(v.multiply(BigDecimal.valueOf(cantidades[i])));}}}BigDecimal igv=sub.multiply(new BigDecimal("0.18")).setScale(2,RoundingMode.HALF_UP);int id;try(PreparedStatement p=c.prepareStatement("INSERT INTO cotizacion(id_cliente,id_usuario,subtotal,igv,total) VALUES(?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setInt(1,cliente);p.setInt(2,usuario);p.setBigDecimal(3,sub);p.setBigDecimal(4,igv);p.setBigDecimal(5,sub.add(igv));p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();id=r.getInt(1);}}for(int i=0;i<ids.length;i++){try(PreparedStatement p=c.prepareStatement("INSERT INTO detalle_cotizacion(id_cotizacion,id_producto,cantidad,precio_unitario,subtotal) VALUES(?,?,?,?,?)")){p.setInt(1,id);p.setInt(2,ids[i]);p.setInt(3,cantidades[i]);p.setBigDecimal(4,precios.get(i));p.setBigDecimal(5,precios.get(i).multiply(BigDecimal.valueOf(cantidades[i])));p.executeUpdate();}}c.commit();return id;}catch(Exception e){c.rollback();if(e instanceof SQLException se)throw se;throw new SQLException(e);}finally{c.setAutoCommit(true);}}}
 public List<Map<String,Object>> listar()throws SQLException{List<Map<String,Object>> l=new ArrayList<>();String q="SELECT q.id_cotizacion,q.fecha,q.estado,q.total,c.razon_social,u.nombre FROM cotizacion q JOIN cliente c ON c.id_cliente=q.id_cliente JOIN usuario u ON u.id_usuario=q.id_usuario ORDER BY q.fecha DESC";try(Connection c=ConexionBD.obtenerConexion();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object> m=new HashMap<>();m.put("id",r.getInt(1));m.put("fecha",r.getTimestamp(2));m.put("estado",r.getString(3));m.put("total",r.getBigDecimal(4));m.put("cliente",r.getString(5));m.put("usuario",r.getString(6));l.add(m);}}return l;}
}